                    let rr: Double = (live ? 7.0 + 5.0 * ez(ha / 0.8) : 7.0)
                    let y: Double = 19.5 - JS.cos(ang) * rr
                    g.fr(22.5 + JS.sin(ang) * rr, y, ((live && y < 25.5) ? 0.55 * (1.0 - ha / 0.9) : 0.0))
                }
            }
            g.line(8.0, 26.0, 37.0, 26.0, 0.3 + 0.45 * JS.min(1.0, steps / 6.0))
            return SceneOut(opts: MatrixDealOptions(stagger: 0.15), flash: 0.08 * h, shake: 0.1 * h)
        }
        public static let SCENES: [MatrixScene] = [scene0, scene1, scene2, scene3, scene4, scene5, scene6]
    }
}
